import type { Plugin } from '@servicenow/sdk-build-core';
/** The contract both the Node loader and browser virtual module must implement */
export type ExternalPluginLoader = (outputName: string, npmPackageName: string) => Plugin[];
/**
 * External plugins loader (Node)
 *
 * Loads pre-bundled external plugins at runtime using dynamic require().
 *
 * In browser bundles (LSP, web), this entire module is replaced by a
 * virtual esbuild module generated in esbuild-plugins.ts
 *
 * Any changes made here must also be made in the generated module
 *
 * @param outputName - Sanitized filename on disk
 * @param npmPackageName - npm package name, used for the node_modules fallback
 */
export declare const loadExternalPlugins: ExternalPluginLoader;
